253	
254	/** A claim's status. It starts DRAFT; DRAFT opens to OPEN, OPEN settles to SETTLED, and DRAFT or
255	 *  OPEN voids to VOID. SETTLED and VOID are final. */
256	public enum ClaimStatus {
257	    DRAFT, OPEN, SETTLED, VOID;
258	
259	    /** The status after moving to {@code to}; refused when this status does not allow it. */
260	    public ClaimStatus moveTo(ClaimStatus to) throws ClaimStatusException {
261	        boolean allowed = switch (to) {
262	            case OPEN -> this == DRAFT;
263	            case SETTLED -> this == OPEN;
264	            case VOID -> this == DRAFT || this == OPEN;
265	            case DRAFT -> false;
266	        };
267	        if (!allowed) {
268	            throw new ClaimStatusException("A " + this + " claim cannot become " + to);
269	        }
270	        return to;
271	    }
272	
273	    /** The audit event recorded when a claim moves to this status. */
274	    public String event() {
275	        return switch (this) {
276	            case OPEN -> "CLAIM_OPENED";
277	            case SETTLED -> "CLAIM_SETTLED";
278	            case VOID -> "CLAIM_VOIDED";
279	            case DRAFT -> "CLAIM_DRAFTED";
280	        };
281	    }
