859	            if (!c.isCounting()) {
860	                c.bind(false, null);
861	            } else {
862	                Rate rate = rates.find(sheetId, person.getGrade(), LocalDate.parse(c.getDate()));
863	                String due = c.due(rate == null ? null : Dues.of(c.getAmount(), rate.pct()));
